import{_ as e,o as i,c as t,ag as r}from"./chunks/framework.CPvOxTBX.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/faq.md","filePath":"zh/guide/faq.md","lastUpdated":1793489430000}'),o={name:"zh/guide/faq.md"};function s(d,a,l,n,h,c){return i(),t("div",null,a[0]||(a[0]=[r(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="词典去哪里下载" tabindex="-1">词典去哪里下载？ <a class="header-anchor" href="#词典去哪里下载" aria-label="Permalink to &quot;词典去哪里下载？&quot;">​</a></h2><p>词悦不自带词典。从 Wiki 的<a href="https://github.com/mumu-lhl/Ciyue/wiki#recommended-dictionaries" target="_blank" rel="noreferrer">推荐词典</a>下载 <code>.mdx</code> / <code>.mdd</code> 文件，或者 StarDict 词典（<code>.ifo</code> / <code>.idx</code> / <code>.dict</code>），然后在 <strong>设置 → 管理词典</strong> 中添加。</p><h2 id="为什么词悦需要-internet-权限" tabindex="-1">为什么词悦需要 INTERNET 权限？ <a class="header-anchor" href="#为什么词悦需要-internet-权限" aria-label="Permalink to &quot;为什么词悦需要 INTERNET 权限？&quot;">​</a></h2><p>词悦用 WebView 渲染词典条目，而 WebView 即使显示本地数据也需要 INTERNET 权限才能工作。该权限还用于检查更新和你配置的第三方服务（如 AI provider）。词悦不会自主发起网络请求。</p><h2 id="f-droid-的版本比-github-的旧-为什么" tabindex="-1">F-Droid 的版本比 GitHub 的旧，为什么？ <a class="header-anchor" href="#f-droid-的版本比-github-的旧-为什么" aria-label="Permalink to &quot;F-Droid 的版本比 GitHub 的旧，为什么？&quot;">​</a></h2><p>F-Droid 按自己的节奏构建和发布应用，所以版本会比 GitHub 晚几天到几周。如果想第一时间收到更新，用 <a href="https://obtainium.imranr.dev/" target="_blank" rel="noreferrer">Obtainium</a> 安装——它直接跟踪 GitHub releases。点<a href="./getting-started.html">快速上手</a> 页面的 Obtainium 徽标即可添加。</p><h2 id="应用更新是怎么工作的-更新通道是什么" tabindex="-1">应用更新是怎么工作的？更新通道是什么？ <a class="header-anchor" href="#应用更新是怎么工作的-更新通道是什么" aria-label="Permalink to &quot;应用更新是怎么工作的？更新通道是什么？&quot;">​</a></h2><p>在 <strong>设置 → 检查更新</strong> 里可以选择更新通道：</p><ul><li><strong>稳定版</strong> —— 仅正式 release，推荐大多数用户使用。</li><li><strong>Beta / Alpha</strong> —— 带新功能的预发布版本，尚在测试。</li><li><strong>Nightly</strong> —— 每天自动构建的最新代码，可能不稳定。</li></ul><p>桌面端通过内置更新器使用同样的三个通道。</p><h2 id="怎么备份单词本和设置" tabindex="-1">怎么备份单词本和设置？ <a class="header-anchor" href="#怎么备份单词本和设置" aria-label="Permalink to &quot;怎么备份单词本和设置？&quot;">​</a></h2><p>到 <strong>设置 → 备份</strong> 导出数据文件（单词本、历史、标签、抽认卡、设置）。妥善保存这个文件，之后可以在同一页面导入。如果要在多设备间持续同步，见<a href="./cloud-sync.html">云同步</a>。</p><h2 id="词典显示乱码或内容缺失怎么办" tabindex="-1">词典显示乱码或内容缺失怎么办？ <a class="header-anchor" href="#词典显示乱码或内容缺失怎么办" aria-label="Permalink to &quot;词典显示乱码或内容缺失怎么办？&quot;">​</a></h2><ul><li>确认同名的 <code>.mdd</code> 资源文件（如果词典有的话）和 <code>.mdx</code> 放在同一目录。</li><li>StarDict 词典要把 <code>.ifo</code>、<code>.idx</code>、<code>.dict</code> 放在同一目录下，且主文件名相同。</li><li>有些词典需要调自定义 CSS：<strong>管理词典 → 词典 → 自定义 CSS</strong>。</li><li>如果某本词典导致查词崩溃，请到 <a href="https://github.com/mumu-lhl/Ciyue/issues" target="_blank" rel="noreferrer">GitHub</a> 提 issue 并注明词典名称。</li></ul><h2 id="同一目录里的-mdx-和-stardict-词典只出现一个" tabindex="-1">同一目录里的 MDX 和 StarDict 词典只出现一个？ <a class="header-anchor" href="#同一目录里的-mdx-和-stardict-词典只出现一个" aria-label="Permalink to &quot;同一目录里的 MDX 和 StarDict 词典只出现一个？&quot;">​</a></h2><p>词悦用「去掉扩展名的路径」来标识一本词典，所以 <code>foo.mdx</code> 与 <code>foo.ifo</code> / <code>foo.idx</code> / <code>foo.dict</code> 会被当成同一本：MDX 会被注册，StarDict 那份会被跳过。想让两本同时出现，请把主文件名区分开，例如 <code>foo-mdx.mdx</code> 与 <code>foo-stardict.ifo</code>。</p><h2 id="怎么在-android-的-koreader-里用词悦" tabindex="-1">怎么在 Android 的 KOReader 里用词悦？ <a class="header-anchor" href="#怎么在-android-的-koreader-里用词悦" aria-label="Permalink to &quot;怎么在 Android 的 KOReader 里用词悦？&quot;">​</a></h2><p>在 <code>koreader</code> 目录下创建 <code>dictionaries.lua</code> 文件，内容如下：</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ciyue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ciyue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org.eu.mumulhl.ciyue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;send&quot; </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>之后就可以在 KOReader 里通过词典动作查词了。</p><h2 id="我的数据存在哪里" tabindex="-1">我的数据存在哪里？ <a class="header-anchor" href="#我的数据存在哪里" aria-label="Permalink to &quot;我的数据存在哪里？&quot;">​</a></h2><ul><li><strong>Android</strong>：应用私有存储（<code>/data/data/org.eu.mumulhl.ciyue/</code>）；词典默认放在应用的文档目录，可在设置里改。</li><li><strong>Windows</strong>：<code>%APPDATA%\\ciyue\\</code>。</li><li><strong>Linux</strong>：<code>~/.local/share/ciyue/</code>（Flatpak 版是 <code>~/.var/app/...</code>）。</li><li><strong>macOS</strong>：<code>~/Library/Application Support/ciyue/</code>。</li></ul><h2 id="怎么参与翻译" tabindex="-1">怎么参与翻译？ <a class="header-anchor" href="#怎么参与翻译" aria-label="Permalink to &quot;怎么参与翻译？&quot;">​</a></h2><p>翻译在 <a href="https://hosted.weblate.org/engage/ciyue/" target="_blank" rel="noreferrer">Weblate</a> 上管理。可以添加新语言或改进现有翻译，不需要会编程。</p><h2 id="发现-bug-有功能建议-去哪里反馈" tabindex="-1">发现 bug / 有功能建议，去哪里反馈？ <a class="header-anchor" href="#发现-bug-有功能建议-去哪里反馈" aria-label="Permalink to &quot;发现 bug / 有功能建议，去哪里反馈？&quot;">​</a></h2><p>到 <a href="https://github.com/mumu-lhl/Ciyue/issues" target="_blank" rel="noreferrer">GitHub</a> 提 issue。请附上应用版本、平台和复现步骤。</p><h2 id="某个翻译源突然不能用了-为什么" tabindex="-1">某个翻译源突然不能用了，为什么？ <a class="header-anchor" href="#某个翻译源突然不能用了-为什么" aria-label="Permalink to &quot;某个翻译源突然不能用了，为什么？&quot;">​</a></h2><p>免费翻译源用的是网页公开接口而非官方 API，服务商可能随时变更或封禁接口。请在翻译设置里停用该源、改用其他源，或换成官方 API 源。详见<a href="./translation.html">翻译</a>页。</p>`,29)]))}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
